qcom_cc_desc.definition:
struct qcom_cc_desc {
	const struct regmap_config *config;
	struct clk_regmap **clks;
	struct critical_clk_offset *critical_clk_en;
	size_t num_critical_clk;
	size_t num_clks;
	const struct qcom_reset_map *resets;
	size_t num_resets;
	struct gdsc **gdscs;
	size_t num_gdscs;
	struct clk_hw **clk_hws;
	size_t num_clk_hws;
	struct clk_vdd_class **clk_regulators;
	size_t num_clk_regulators;
	struct icc_path *path;
};

clk_regmap.definition:
struct clk_regmap {
	struct clk_hw hw;
	struct regmap *regmap;
	unsigned int enable_reg;
	unsigned int enable_mask;
	bool enable_is_inverted;
	struct clk_vdd_class_data vdd_data;
	struct clk_regmap_ops *ops;
	struct list_head list_node;
	struct device *dev;
	struct clk_crm *crm;
	u8 crm_vcd;
	u8 crm_base_node;
	u8 crm_num_node;
#define QCOM_CLK_IS_CRITICAL BIT(0)
#define QCOM_CLK_BOOT_CRITICAL BIT(1)
	unsigned long flags;
};

clk_vdd_class.definition:
struct clk_vdd_class {
	const char		*class_name;
	struct regulator	**regulator;
	const char		**regulator_names;
	int			num_regulators;
	int			*vdd_uv;
	int			*level_votes;
	int			num_levels;
	int			cur_level;
};

clk_vdd_class_data.definition:
struct clk_vdd_class_data {
	struct clk_vdd_class	*vdd_class;
	struct clk_vdd_class	**vdd_classes;
	unsigned long		*rate_max;
	int			num_rate_max;
	int			vdd_level;
	int			num_vdd_classes;
};

clk_rcg2.definition:
struct clk_rcg2 {
	u32			cmd_rcgr;
	u8			mnd_width;
	u8			hid_width;
	u8			safe_src_index;
	const struct parent_map	*parent_map;
	const struct freq_tbl	*freq_tbl;
	unsigned long		configured_freq;
	unsigned long		current_freq;
	bool			enable_safe_config;
	struct clk_regmap	clkr;
	u8			cfg_off;
	u32			parked_cfg;
	u8			flags;
#define FORCE_ENABLE_RCG	BIT(0)
#define HW_CLK_CTRL_MODE	BIT(1)
#define DFS_SUPPORT		BIT(2)
	bool			freq_populated;
	bool			hw_clk_ctrl;
};
